  async function downloadTemplate(type,trigger){const template=importTemplates[type],button=trigger||document.querySelector(`[data-template="${type}"]`);button.disabled=true;try{const response=await fetch(`/api/import/template/${encodeURIComponent(type)}`,{credentials:'same-origin'});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||'Template gagal diunduh.')}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=template.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Template Excel siap diisi.')}catch(error){toast(error.message)}finally{button.disabled=false}}
  function csvDelimiter(text){const line=(String(text).replace(/^\ufeff/,'').split(/\r?\n/).find(value=>value.trim())||''),counts={',':0,';':0,'\t':0};let quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'){if(quoted&&line[i+1]==='"')i++;else quoted=!quoted}else if(!quoted&&Object.prototype.hasOwnProperty.call(counts,char))counts[char]++}const ranked=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return ranked[0][1]?ranked[0][0]:','}
  function parseCSV(text){const delimiter=csvDelimiter(text),rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(quoted){if(char==='"'&&text[i+1]==='"'){cell+='"';i++}else if(char==='"')quoted=false;else cell+=char}else if(char==='"')quoted=true;else if(char===delimiter){row.push(cell.trim());cell=''}else if(char==='\n'){row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);row=[];cell=''}else if(char!=='\r')cell+=char}row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);if(!rows.length)return[];const headers=rows.shift().map(value=>value.replace(/^\ufeff/,'').trim());return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])))}
  function bufferToBase64(buffer){const bytes=new Uint8Array(buffer),parts=[];for(let index=0;index<bytes.length;index+=32768)parts.push(String.fromCharCode(...bytes.subarray(index,index+32768)));return btoa(parts.join(''))}
  async function uploadImport(type){const input=document.querySelector(`[data-import="${type}"]`),status=byId('importStatus'+type[0].toUpperCase()+type.slice(1)),button=document.querySelector(`[data-upload="${type}"]`),file=input.files[0],template=importTemplates[type];if(!file){toast('Pilih file Excel atau CSV terlebih dahulu.');return}const filename=file.name.toLowerCase();let payload;if(filename.endsWith('.xlsx')){if(file.size>2*1024*1024){toast('Ukuran file Excel maksimal 2 MB.');return}status.textContent='Membaca dan memvalidasi file Excel...';payload={type,file_name:file.name,file_base64:bufferToBase64(await file.arrayBuffer())}}else if(filename.endsWith('.csv')){const rows=parseCSV(await file.text());if(!rows.length){toast('File CSV tidak memiliki data.');return}if(rows.length>200){toast('Maksimal 200 baris per file.');return}const missing=template.headers.filter(header=>!(header in rows[0]));if(missing.length){toast('Kolom template tidak lengkap: '+missing.join(', '));return}status.textContent=`Memvalidasi ${rows.length} baris CSV...`;payload={type,rows}}else{toast('Gunakan file .xlsx atau .csv.');return}button.disabled=true;try{const result=await api('/api/import',{method:'POST',body:JSON.stringify(payload)});status.textContent=`Selesai: ${result.imported} baris masuk ke Satu Data DDU.${result.created_donors?` ${result.created_donors} donatur/mitra baru dibuat otomatis.`:''}${result.updated_targets?` ${result.updated_targets} target diperbarui.`:''}${result.pending_approvals?` ${result.pending_approvals} menunggu persetujuan.`:''}`;input.value='';input.closest('.upload-label').childNodes[0].textContent='Pilih Excel / CSV';await refreshCentralData();toast(result.message)}catch(error){status.textContent='Impor dibatalkan: '+error.message;toast('Tidak ada data yang disimpan karena validasi gagal.')}finally{button.disabled=false}}
