  function eligibleBudgetUsageRequests(){return currentBudgetRequests.filter(item=>item.division===currentUser?.division&&['disbursed','accountability'].includes(item.status)&&Number(item.remaining_amount)>0)}
  function syncBudgetUsageSelection(){
    const select=byId('budgetUsageRequest'),amount=byId('budgetUsageAmount'),submit=byId('budgetUsageSubmit'),availability=byId('budgetUsageAvailability'),help=byId('budgetUsageRequestHelp');
    if(!select)return;
    const previous=select.value,items=eligibleBudgetUsageRequests();
    select.replaceChildren(new Option(items.length?'Pilih kode pengajuan':'Belum ada pengajuan yang siap dilaporkan',''),...items.map(item=>new Option(`${item.request_code} · ${item.purpose} · sisa ${rupiah(item.remaining_amount)}`,String(item.id))));
    select.value=items.some(item=>String(item.id)===previous)?previous:(items[0]?String(items[0].id):'');
    const selected=items.find(item=>String(item.id)===select.value),disabled=!selected;
    [byId('budgetUsageDate'),byId('budgetUsageCategory'),amount,byId('budgetUsageProof'),byId('budgetUsageDescription'),submit].forEach(control=>control.disabled=disabled);
    select.disabled=!items.length;
    availability.textContent=items.length?`${items.length} pengajuan siap LPJ`:`Belum ada pencairan untuk ${displayUnit(currentUser?.division||'unit ini')}`;
    availability.classList.toggle('ready',Boolean(items.length));
    if(selected){amount.max=String(selected.remaining_amount);help.textContent=`Dana dicairkan ${rupiah(selected.disbursed_amount)} · sudah digunakan ${rupiah(selected.used_amount)} · maksimal input saat ini ${rupiah(selected.remaining_amount)}.`}
    else{amount.removeAttribute('max');help.textContent='Pengajuan harus diverifikasi, disetujui sesuai batas, dan dicairkan oleh Bendahara sebelum LPJ dapat dicatat.'}
  }
