  byId('budgetSettingsForm').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/budget-settings',{method:'PUT',body:JSON.stringify({chair_approval_limit:Number(byId('budgetChairApprovalLimit').value)})});await Promise.all([loadBudgetSettings(),loadBudgetRequests()]);toast(result.message)}catch(error){toast(error.message)}};
  function budgetActions(item){const treasurer=currentUser?.division==='Bendahara',chair=currentUser?.role==='ketua',owner=currentUser?.division===item.division;let html='';if(treasurer&&item.status==='submitted')html='<button class="primary" data-budget-action="treasurer_approve">Verifikasi</button><button class="secondary" data-budget-action="reject">Tolak</button>';if(chair&&item.status==='treasurer_approved')html='<button class="primary" data-budget-action="chair_approve">Setujui</button><button class="secondary" data-budget-action="reject">Tolak</button>';if(treasurer&&item.status==='chair_approved')html='<button class="primary" data-budget-action="disburse">Catat pencairan</button>';if(owner&&['disbursed','accountability'].includes(item.status))html+=`<form class="budget-usage-form" data-budget-use><input type="date" name="date" value="${today()}" required><input name="category" placeholder="Kategori belanja" required><input type="number" min="1" max="${item.remaining_amount}" name="amount" placeholder="Nominal" required><input name="description" placeholder="Rincian penggunaan" required><input name="proof_note" placeholder="Nomor/keterangan bukti"><button class="primary">Tambah penggunaan</button></form>`;return html}
  function bindBudgetActions(){byId('budgetList').querySelectorAll('[data-budget-action]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-budget-id]'),action=button.dataset.budgetAction,note=action==='reject'?(prompt('Alasan penolakan:')||''):'';if(action==='reject'&&!note)return;try{const result=await api('/api/budget-requests',{method:'PUT',body:JSON.stringify({id:Number(card.dataset.budgetId),action,note})});await Promise.all([loadBudgetRequests(),loadFinances()]);toast(result.message)}catch(error){toast(error.message)}});byId('budgetList').querySelectorAll('[data-budget-use]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),id=Number(form.closest('[data-budget-id]').dataset.budgetId);try{const result=await saveBudgetUsage(id,values);form.reset();await Promise.all([loadBudgetRequests(),loadFinances()]);toast(result.message)}catch(error){toast(error.message)}})}
  async function loadBudgetRequests(){try{const data=await api('/api/budget-requests');currentBudgetRequests=data.items||[];const requested=currentBudgetRequests.reduce((sum,item)=>sum+item.amount,0),disbursed=currentBudgetRequests.reduce((sum,item)=>sum+item.disbursed_amount,0),used=currentBudgetRequests.reduce((sum,item)=>sum+item.used_amount,0);byId('budgetSummary').innerHTML=`<article class="card kpi"><span class="kpi-label">Total diajukan</span><strong>${rupiah(requested)}</strong></article><article class="card kpi"><span class="kpi-label">Sudah dicairkan</span><strong>${rupiah(disbursed)}</strong></article><article class="card kpi"><span class="kpi-label">Sudah digunakan</span><strong>${rupiah(used)}</strong></article><article class="card kpi"><span class="kpi-label">Belum dipertanggungjawabkan</span><strong>${rupiah(disbursed-used)}</strong></article>`;byId('budgetList').innerHTML=currentBudgetRequests.length?currentBudgetRequests.map(item=>{const requiresChair=Boolean(Number(item.chair_approval_required)),chairStep=requiresChair?`<span class="${item.chair_at?'done':''}">Ketua</span>`:'<span class="done skipped">Tanpa ACC Ketua</span>',approvalNote=requiresChair?`Wajib ACC Ketua mulai ${rupiah(item.chair_approval_limit)}`:`Di bawah batas ${rupiah(item.chair_approval_limit)}`;return `<article class="card budget-card" data-budget-id="${item.id}"><div class="budget-card-head"><div><span class="budget-code">${escapeHtml(item.request_code)}</span><h4>${escapeHtml(item.division)} · ${rupiah(item.amount)}</h4><p>${escapeHtml(item.purpose)}</p><span class="budget-approval-note">${approvalNote}</span></div><span class="pill ${item.status==='completed'?'green':item.status==='rejected'?'red':'yellow'}">${budgetStatuses[item.status]||item.status}</span></div><div class="budget-flow"><span class="${item.treasurer_at?'done':''}">Bendahara</span>${chairStep}<span class="${item.disbursed_at?'done':''}">Dicairkan</span><span class="${item.status==='completed'?'done':''}">LPJ</span></div>${item.disbursed_amount?`<div class="budget-amounts"><span>Dicairkan <b>${rupiah(item.disbursed_amount)}</b></span><span>Penggunaan <b>${rupiah(item.used_amount)}</b></span><span>Sisa <b>${rupiah(item.remaining_amount)}</b></span></div>`:''}${item.usages.length?`<div class="budget-usages">${item.usages.map(use=>`<div><span>${escapeHtml(use.usage_date)} · ${escapeHtml(use.category)}</span><b>${rupiah(use.amount)}</b><small>${escapeHtml(use.description)}${use.proof_note?' · Bukti: '+escapeHtml(use.proof_note):''}</small></div>`).join('')}</div>`:''}<div class="budget-actions">${budgetActions(item)}</div></article>`}).join(''):'<article class="card empty-row">Belum ada pengajuan anggaran.</article>';bindBudgetActions();syncBudgetUsageSelection()}catch(error){currentBudgetRequests=[];syncBudgetUsageSelection();toast(error.message)}}
  async function loadBudgetFinanceReport(){try{const data=await api('/api/finance/budget-report?'+rangeQuery()),summary=data.summary||{},range=activeRange();byId('budgetReportRequested').textContent=rupiah(summary.requested);byId('budgetReportDisbursed').textContent=rupiah(summary.disbursed);byId('budgetReportUsed').textContent=rupiah(summary.used);byId('budgetReportOutstanding').textContent=rupiah(summary.outstanding);byId('budgetReportPeriod').textContent=`${range.label} · ${data.date_from} s.d. ${data.date_to}`;byId('budgetReportRows').innerHTML=data.items.length?data.items.map(item=>{const usages=item.usages||[],statusClass=item.status==='completed'?'green':item.status==='rejected'?'red':'yellow',detail=usages.length?`<details class="budget-report-details"><summary>${usages.length} penggunaan · ${rupiah(item.period_used)}</summary>${usages.map(use=>`<div><b>${escapeHtml(use.usage_date)} · ${escapeHtml(use.category)}</b><span>${rupiah(use.amount)}</span><small>${escapeHtml(use.description)}${use.proof_note?' · Bukti: '+escapeHtml(use.proof_note):''}</small></div>`).join('')}</details>`:'<span class="reference-usage">Tidak ada penggunaan pada periode</span>';return `<tr><td><b class="budget-code">${escapeHtml(item.request_code)}</b></td><td>${escapeHtml(item.division)}</td><td>${escapeHtml(item.purpose)}</td><td>${rupiah(item.amount)}</td><td>${rupiah(item.disbursed_amount)}</td><td><b>${rupiah(item.used_amount)}</b><small class="budget-period-used">Periode: ${rupiah(item.period_used)}</small></td><td>${rupiah(item.remaining_amount)}</td><td><span class="pill ${statusClass}">${escapeHtml(budgetStatuses[item.status]||item.status)}</span></td><td>${detail}</td></tr>`}).join(''):'<tr><td colspan="9" class="empty-row">Belum ada pengajuan atau penggunaan anggaran pada periode ini.</td></tr>'}catch(error){byId('budgetReportRows').innerHTML='<tr><td colspan="9" class="empty-row">Laporan penggunaan anggaran belum dapat dimuat.</td></tr>';toast(error.message)}}
  async function loadFinancialEfficiency(){if(currentUser?.role==='pengawas'||!byId('financialEfficiencyCard'))return;try{const query=new URLSearchParams({date_from:activeRange().from,date_to:activeRange().to});if(['ketua','sekretaris'].includes(currentUser?.role)&&dashboardDivision)query.set('division',dashboardDivision);const data=await api('/api/dashboard/financial-efficiency?'+query.toString()),ratio=Number(data.ratio||0),institution=data.scope==='institution',range=activeRange(),progress=byId('financialEfficiencyBar'),container=progress.parentElement;byId('financialEfficiencyTitle').textContent=institution?'Rasio Biaya Operasional Lembaga':'Rasio Biaya Kerja '+data.scope_label;byId('financialEfficiencyBasis').textContent=institution?'Akumulasi pengeluaran Ketua, Sekretaris, Bendahara, dan Administrasi dibanding total pemasukan donasi seluruh unit.':'Pengeluaran terealisasi dibanding pemasukan donasi unit pada periode yang sama.';byId('financialEfficiencyRatio').textContent=ratio.toLocaleString('id-ID',{maximumFractionDigits:1})+'%';byId('financialEfficiencyIncome').textContent=rupiah(data.income);byId('financialEfficiencyExpense').textContent=rupiah(data.expense);byId('financialEfficiencyNet').textContent=rupiah(data.net);byId('financialEfficiencyScope').textContent=`${data.scope_label} · ${range.label}`;progress.style.width=Math.min(100,Math.max(0,ratio))+'%';container.setAttribute('aria-valuenow',String(ratio));container.setAttribute('aria-valuemax',String(Math.max(100,Math.ceil(ratio))));byId('financialEfficiencyCard').classList.toggle('over-budget',ratio>100)}catch(error){toast(error.message)}}
  byId('budgetRequestForm').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/budget-requests',{method:'POST',body:JSON.stringify({division:byId('budgetDivision').value,amount:Number(byId('budgetAmount').value),purpose:byId('budgetPurpose').value})});event.target.reset();applyUser(currentUser);await loadBudgetRequests();toast(result.message)}catch(error){toast(error.message)}};
  const loadFinancesAccountingBase=loadFinances;loadFinances=async()=>{await loadFinancesAccountingBase();try{const data=currentFinanceData,donationCount=Number(data.summary.donation_count||0);byId('cashOutTotal').textContent=rupiah(donationCount?Number(data.summary.income||0)/donationCount:0);if(['ketua','sekretaris'].includes(currentUser?.role)||['Bendahara','Administrasi'].includes(currentUser?.division)){const units=[...new Set([...unitNames,...data.items.map(item=>item.division)])],totals=Object.fromEntries(units.map(unit=>[unit,{income:0,expense:0}]));data.items.forEach(item=>{if(!totals[item.division])return;if(item.transaction_type==='pemasukan')totals[item.division].income+=item.amount;else if(item.accounting_type!=='internal_advance')totals[item.division].expense+=item.amount});byId('treasuryRows').innerHTML=units.map(unit=>`<tr><td><b>${escapeHtml(unit)}</b></td><td>${rupiah(totals[unit].income)}</td><td>${rupiah(totals[unit].expense)}</td><td><b>${rupiah(totals[unit].income-totals[unit].expense)}</b></td></tr>`).join('')}await Promise.all([loadBudgetFinanceReport(),loadFinancialEfficiency()])}catch(error){toast(error.message)}};
  document.getElementById('date').valueAsDate=new Date();
  const ctx=document.getElementById('trendChart');if(window.Chart)new Chart(ctx,{type:'bar',data:{labels:['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep'],datasets:[{label:'Target',data:[80,90,95,100,110,120,125,135,145],backgroundColor:'#dfe7e3',borderRadius:7,barThickness:18},{label:'Realisasi',data:[60,72,81,86,95,103,106,118,132],type:'line',borderColor:'#177a5b',backgroundColor:'#177a5b',tension:.4,pointRadius:4,pointBorderWidth:2,pointBackgroundColor:'#fff',pointBorderColor:'#177a5b'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,grid:{color:'#eef1ef'},border:{display:false},ticks:{font:{size:10},callback:v=>'Rp '+v+' jt'}}}}});
  const loadWorkspaceBase=loadWorkspace;loadWorkspace=()=>{loadWorkspaceBase();loadDistributionRoutes();loadAcademicYears();loadBudgetSettings();loadBudgetRequests();if(['ketua','sekretaris'].includes(currentUser?.role))loadPolicyApprovals()};
  checkSession();
